h&&tex[pos]!==stop){const ch=tex[pos];if(ch==='{'||ch==='}')return null;if(ch==='\\'){const item=parseCommand();if(item===null)return null;nodes.push(item);continue;}if(ch==='^'||ch==='_'){pos++;const body=tex[pos]==='{'?parseGroup():pos<tex.length?[tex[pos++]]:null;if(body===null||!appendScript(nodes,ch==='^'?'sup':'sub',body))return null;continue;}nodes.push(ch);pos++;}return nodes;};const nodes=parseUntil('');return nodes===null||pos!==tex.length?null:nodes;}
  richMath(value,key,block){const nodes=this.richTexParse(value);if(nodes===null)return null;const label='数式 '+this.richTexLabel(value);return React.createElement('span',{key:key,className:'kt-math kt-rich-math'+(block?' kt-rich-math-block':''),role:'math','aria-label':label,title:label},nodes);}
  richInline(text,keyPrefix){const out=[];let plain='',i=0,key=0;const flush=()=>{if(plain){out.push(this.withFurigana(plain));plain='';}};const takeDelimited=(marker,tag,className)=>{if(!text.startsWith(marker,i))return false;const end=text.indexOf(marker,i+marker.length);if(end<0||end===i+marker.length)return false;flush();out.push(React.createElement(tag,{key:keyPrefix+'-'+(key++),className:className},this.richInline(text.slice(i+marker.length,end),keyPrefix+'-'+key)));i=end+marker.length;return true;};while(i<text.length){const math=this.richMathDelimiterAt(text,i);if(math){const node=this.richMath(math.body,keyPrefix+'-math-'+(key++),math.source.startsWith('\\[')||math.source.startsWith('$$'));if(node){flush();out.push(node);i=math.end;continue;}}if(text[i]==='`'){const end=text.indexOf('`',i+1);if(end>i+1){flush();out.push(React.createElement('code',{key:keyPrefix+'-'+(key++),className:'kt-rich-code'},text.slice(i+1,end)));i=end+1;continue;}}if((text.startsWith('**',i)||text.startsWith('__',i))&&takeDelimited(text.slice(i,i+2),'strong','kt-rich-strong'))continue;if((text[i]==='*'||text[i]==='_')&&takeDelimited(text[i],'em','kt-rich-emphasis'))continue;plain+=text[i];i++;}flush();return out;}
  withRichInline(source){if(source===null||source===undefined)return React.createElement(React.Fragment,null);if(Array.isArray(source)||React.isValidElement(source))return source;return React.createElement(React.Fragment,null,this.richInline(String(source),'rich-inline'));}
  withRichText(source){if(source===null||source===undefined)return React.createElement(React.Fragment,null);if(Array.isArray(source)||React.isValidElement(source))return source;const text=String(source),blocks=text.split(/\n{2,}/),nodes=[];let key=0;for(const block of blocks){const lines=block.split('\n'),heading=lines.length===1&&lines[0].match(/^(#{1,6})\s+(.+)$/),unordered=lines.length>0&&lines.every(line=>/^[-*+]\s+/.test(line)),ordered=lines.length>0&&lines.every(line=>/^\d+[.)]\s+/.test(line));if(heading){const level=Math.min(6,heading[1].length);nodes.push(React.createElement('h'+level,{key:'rich-h-'+(key++),className:'kt-rich-heading'},this.richInline(heading[2],'rich-h-'+key)));continue;}if(unordered||ordered){const items=lines.map((line,index)=>React.createElement('li',{key:'rich-li-'+key+'-'+index},this.richInline(line.replace(unordered?/^[-*+]\s+/:/^\d+[.)]\s+/,''),'rich-li-'+key+'-'+index)));nodes.push(React.createElement(ordered?'ol':'ul',{key:'rich-list-'+(key++),className:'kt-rich-list'},items));continue;}const inline=[];lines.forEach((line,index)=>{if(index)inline.push(React.createElement('br',{key:'rich-br-'+key+'-'+index}));inline.push(...this.richInline(line,'rich-p-'+key+'-'+index));});nodes.push(React.createElement('p',{key:'rich-p-'+(key++),className:'kt-rich-paragraph'},inline));}return React.createElement(React.Fragment,null,nodes);}
  withLearningNotation(value){if(value===null||value===undefined||Array.isArray(value)||React.isValidElement(value))return value;const text=String(value);let out=[],plain='',changed=false,i=0;const flush=()=>{if(plain){out.push(plain);plain='';}};while(i<text.length){const fraction=this.notationFractionAt(text,i);if(fraction){flush();out.push(this.notationFraction(fraction.numerator,fraction.denominator,'fraction-'+i));changed=true;i+=fraction.source.length;continue;}const ratio=this.notationRatioAt(text,i);if(ratio){flush();out.push(this.notationRatio(ratio.left,ratio.mark,ratio.right,'ratio-'+i));changed=true;i+=ratio.source.length;continue;}const radical=text[i]==='√'&&text.slice(i+1).match(/^(\d+(?:\.\d+)?|[A-Za-zπ])/);if(radical){flush();const radicand=radical[1];out.push(this.notationRadical(radicand,'radical-'+i));changed=true;i+=1+radicand.length;continue;}const power=(text[i+1]==='²'||text[i+1]==='³')&&(/[0-9A-Za-zπ□)]/.test(text[i]||''));if(power){flush();out.push(this.notationSuperscript(text[i],text[i+1],'power-'+i));changed=true;i+=2;continue;}if(this.notationOperatorAt(text,i)){flush();const sourceOp=text[i],op=sourceOp==='-'?'−':sourceOp==='*'?'×':sourceOp;out.push(this.notationOperator(op,'operator-'+i,this.notationUnaryAt(text,i)));changed=true;i++;continue;}plain+=text[i];i++;}flush();return changed?out:text;}
