    private static string BuildLearningNotationStyles()
    {
        return """
<style id="kt-learning-notation">
  .kt-math { font-family: ui-rounded, "Arial Rounded MT Bold", "Noto Sans JP", sans-serif; font-variant-numeric: tabular-nums; }
  .kt-fraction { display:inline-grid; grid-template-rows:auto auto; vertical-align:middle; min-width:1.14em; margin:0 .07em; text-align:center; line-height:1.02; white-space:nowrap; }
  .kt-fraction-numerator { display:block; padding:0 .16em .06em; border-bottom:.075em solid currentColor; }
  .kt-fraction-denominator { display:block; padding:.06em .16em 0; }
  .kt-power { display:inline-flex; align-items:baseline; vertical-align:baseline; white-space:nowrap; }
  .kt-superscript { margin-left:.025em; font-size:.58em; font-weight:900; line-height:1; vertical-align:super; }
  .kt-radical { display:inline-flex; align-items:flex-start; vertical-align:middle; white-space:nowrap; line-height:1.02; }
  .kt-radical-sign { font-size:1.14em; line-height:.96; }
  .kt-radicand { border-top:.075em solid currentColor; padding:.03em .08em 0 .1em; }
  .kt-ratio { display:inline-flex; align-items:baseline; vertical-align:baseline; white-space:nowrap; }
  .kt-ratio-mark { padding:0 .08em; font-weight:900; }
  .kt-math-operator { display:inline-block; min-width:.45em; text-align:center; white-space:pre; }
  .kt-rich-math { display:inline-flex; align-items:baseline; gap:.02em; margin:0 .05em; white-space:nowrap; }
  .kt-rich-math-block { display:flex; width:max-content; max-width:100%; margin:.48em auto; justify-content:center; overflow-x:auto; }
  .kt-tex-script { display:inline-flex; align-items:baseline; }
  .kt-tex-sup,.kt-tex-sub { font-size:.62em; font-weight:900; line-height:1; }
  .kt-tex-sup { vertical-align:super; transform:translateY(-.38em); }
  .kt-tex-sub { vertical-align:sub; transform:translateY(.22em); }
  .kt-rich-paragraph { margin:.35em 0; }
  .kt-rich-heading { margin:.4em 0 .22em; font-size:1.05em; font-weight:900; line-height:1.2; }
  .kt-rich-list { margin:.35em 0; padding-inline-start:1.45em; text-align:left; }
  .kt-rich-code { padding:.08em .28em; border-radius:.3em; background:#f0e8da; font-family:ui-monospace, monospace; font-size:.88em; }
  @media (min-width:761px) and (max-height:700px) {
    div:has(> .kt-question-metadata):has(.kt-question-prompt .kt-rich-math) { box-sizing:border-box!important; height:100vh!important; min-height:100vh!important; padding:10px 32px!important; overflow:hidden!important; }
    .kt-feedback-screen:has(.kt-feedback-explanation .kt-rich-math) { box-sizing:border-box!important; min-height:100dvh!important; padding:12px var(--kt-space-6)!important; }
    div:has(> .kt-question-metadata):has(.kt-question-prompt .kt-rich-math) > .kt-question-metadata { display:grid!important; grid-template-columns:repeat(4,minmax(0,1fr)); gap:4px!important; margin-top:4px!important; align-items:stretch!important; }
    div:has(> .kt-question-metadata):has(.kt-question-prompt .kt-rich-math) > .kt-question-metadata > span { box-sizing:border-box!important; width:auto!important; height:32px!important; min-height:32px!important; padding:3px 6px!important; border-width:2px!important; border-radius:10px!important; font-size:12px!important; line-height:1.1!important; white-space:nowrap!important; overflow:hidden!important; text-overflow:ellipsis!important; }
    div:has(> .kt-question-metadata):has(.kt-question-prompt .kt-rich-math) > .kt-question-metadata + div { margin-top:4px!important; min-height:0!important; }
    .kt-question-prompt:has(.kt-rich-math) { padding:0 12px!important; margin:0 auto 2px!important; font-size:clamp(36px,7vh,42px)!important; line-height:1.25!important; }
    .kt-question-prompt:has(.kt-rich-math) .kt-rich-paragraph { margin:.05em 0!important; }
    .kt-choice-grid:has(.kt-rich-math) { gap:6px!important; margin-top:4px!important; }
    .kt-choice-grid:has(.kt-rich-math) .kt-choice-button { min-height:64px!important; padding:4px 14px!important; font-size:22px!important; line-height:1.2!important; }
    div:has(> .kt-question-metadata):has(.kt-question-prompt .kt-rich-math) > [role="button"][aria-label="答えと説明を見る"] { box-sizing:border-box!important; height:44px!important; min-height:44px!important; margin-top:4px!important; padding:4px 18px!important; font-size:14px!important; }
  }
  @media (max-width:480px) { .kt-fraction { margin:0 .045em; } .kt-fraction-numerator,.kt-fraction-denominator { padding-left:.1em; padding-right:.1em; } }
</style>
""";
    }
